  5	public enum OrderStatus {
  6	    AWAITING_PAYMENT, PAID, SHIPPED, DELIVERED, CANCELLED;
  7	
  8	    public boolean canTransitionTo(OrderStatus next) {
  9	        return allowedNext().contains(next);
 10	    }
 11	
 12	    private Set<OrderStatus> allowedNext() {
 13	        return switch (this) {
 14	            case AWAITING_PAYMENT -> Set.of(PAID, CANCELLED);
 15	            case PAID -> Set.of(SHIPPED, CANCELLED);
 16	            case SHIPPED -> Set.of(DELIVERED);
