 21	package br.com.loja.pedidos.order;
 22	
 23	import br.com.loja.pedidos.catalog.ProductRepository;
 24	import br.com.loja.pedidos.checkout.CheckoutRequest;
 25	import br.com.loja.pedidos.checkout.CheckoutService;
 26	import br.com.loja.pedidos.checkout.OrderSummary;
 27	import br.com.loja.pedidos.common.ApiException;
 28	import br.com.loja.pedidos.customer.CustomerRepository;
 29	import java.time.Clock;
 30	import java.time.Duration;
 31	import java.time.Instant;
 32	import java.time.OffsetDateTime;
 33	import java.time.temporal.ChronoUnit;
 34	import java.util.Comparator;
 35	import java.util.List;
 36	import java.util.UUID;
 37	import java.util.function.Supplier;
 38	import org.springframework.stereotype.Service;
 39	import org.springframework.transaction.support.TransactionTemplate;
 40	
 41	@Service
 42	public class OrderService {
 43	
 44	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 45	    private static final String PAYMENT_OK = "OK";
 46	
 47	    private final CheckoutService checkout;
 48	    private final OrderRepository orders;
 49	    private final ProductRepository products;
 50	    private final CustomerRepository customers;
 51	    private final List<OrderLifecycleListener> listeners;
 52	    private final TransactionTemplate tx;
 53	    private final Clock clock;
 54	
 55	    public OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
 56	                        CustomerRepository customers, List<OrderLifecycleListener> listeners,
 57	                        TransactionTemplate tx, Clock clock) {
 58	        this.checkout = checkout;
 59	        this.orders = orders;
 60	        this.products = products;
 61	        this.customers = customers;
 62	        this.listeners = listeners;
 63	        this.tx = tx;
 64	        this.clock = clock;
 65	    }
 66	
 67	    public OrderSummary summarize(CheckoutRequest request) {
 68	        return checkout.summarize(request);
 69	    }
 70	
 71	    public Order register(CheckoutRequest request) {
 72	        // computed before opening the transaction: it may call the carrier
 73	        OrderSummary summary = checkout.summarize(request);
 74	        List<Order.Item> items = request.items().stream()
 75	                .map(i -> new Order.Item(i.sku(), i.quantity())).toList();
 76	        Order order = new Order(UUID.randomUUID().toString(), OrderStatus.AWAITING_PAYMENT,
 77	                clock.instant().truncatedTo(ChronoUnit.SECONDS), summary, items, null);
 78	        customers.createIfAbsent(request.cpf(), request.email());
 79	        return inTransaction(() -> {
 80	            orders.insert(request.cpf(), request.email(), order);
 81	            return order;
 82	        });
 83	    }
 84	
 85	    public Order get(String id) {
 86	        return orders.find(id).orElseThrow(OrderService::notFound).order();
 87	    }
 88	
 89	    public Order confirmPayment(String id, String transactionId, String paidAt) {
 90	        PaymentResult result = inTransaction(() -> doConfirmPayment(id, transactionId, paidAt));
 91	        if (result.error() != null) {
 92	            throw result.error();
 93	        }
 94	        return result.order();
 95	    }
 96	
 97	    public Order ship(String id, String trackingCode) {
 98	        return inTransaction(() -> {
 99	            StoredOrder stored = lock(id);
100	            if (trackingCode == null || trackingCode.isBlank()) {
101	                throw ApiException.unprocessable("INVALID_ORDER");
102	            }
103	            requireTransition(stored, OrderStatus.SHIPPED);
104	            orders.updateShipment(id, trackingCode);
105	            StoredOrder shipped = reload(id);
106	            listeners.forEach(l -> l.onShipped(shipped));
107	            return shipped.order();
108	        });
109	    }
110	
111	    public Order deliver(String id) {
112	        return inTransaction(() -> {
113	            requireTransition(lock(id), OrderStatus.DELIVERED);
114	            orders.updateStatus(id, OrderStatus.DELIVERED);
115	            return reload(id).order();
116	        });
117	    }
118	
119	    public Order cancel(String id) {
120	        return inTransaction(() -> {
121	            StoredOrder stored = lock(id);
122	            requireTransition(stored, OrderStatus.CANCELLED);
123	            cancelLocked(stored);
124	            return reload(id).order();
125	        });
126	    }
127	
128	    private PaymentResult doConfirmPayment(String id, String transactionId, String paidAtText) {
129	        StoredOrder stored = lock(id);
130	        Instant paidAt = parseInstant(paidAtText);
131	        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
132	            throw ApiException.unprocessable("INVALID_ORDER");
133	        }
134	        String previous = orders.findPaymentOutcome(id, transactionId).orElse(null);
135	        if (previous != null) {
136	            return PAYMENT_OK.equals(previous)
137	                    ? new PaymentResult(stored.order(), null)
138	                    : new PaymentResult(null, ApiException.conflict(previous));
139	        }
140	        requireTransition(stored, OrderStatus.PAID);
141	
142	        Order order = stored.order();
143	        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
144	            return refuse(stored, transactionId, "ORDER_EXPIRED");
145	        }
146	        // lock in a fixed order so that concurrent payments cannot deadlock
147	        List<Order.Item> items = order.items().stream().sorted(Comparator.comparing(Order.Item::sku)).toList();
148	        boolean enough = true;
149	        for (Order.Item item : items) {
150	            enough &= products.lockStock(item.sku()) >= item.quantity();
151	        }
152	        if (!enough) {
153	            return refuse(stored, transactionId, "INSUFFICIENT_STOCK");
154	        }
155	        items.forEach(i -> products.decrementStock(i.sku(), i.quantity()));
156	        orders.updateStatus(id, OrderStatus.PAID);
157	        orders.recordPaymentOutcome(id, transactionId, PAYMENT_OK);
158	        StoredOrder paid = reload(id);
159	        listeners.forEach(l -> l.onPaid(paid));
160	        return new PaymentResult(paid.order(), null);
161	    }
162	
163	    private PaymentResult refuse(StoredOrder stored, String transactionId, String code) {
164	        orders.recordPaymentOutcome(stored.order().id(), transactionId, code);
165	        cancelLocked(stored);
166	        return new PaymentResult(null, ApiException.conflict(code));
167	    }
168	
169	    /** Cancels an order whose row is already locked, giving back whatever the payment had taken. */
170	    private void cancelLocked(StoredOrder stored) {
171	        boolean wasPaid = stored.order().status() == OrderStatus.PAID;
172	        if (wasPaid) {
173	            stored.order().items().stream().sorted(Comparator.comparing(Order.Item::sku))
174	                    .forEach(i -> products.incrementStock(i.sku(), i.quantity()));
175	        }
176	        orders.updateStatus(stored.order().id(), OrderStatus.CANCELLED);
177	        StoredOrder cancelled = reload(stored.order().id());
178	        listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
179	    }
180	
181	    private StoredOrder lock(String id) {
182	        return orders.findForUpdate(id).orElseThrow(OrderService::notFound);
183	    }
184	
185	    private StoredOrder reload(String id) {
186	        return orders.find(id).orElseThrow(OrderService::notFound);
187	    }
188	
189	    private static void requireTransition(StoredOrder stored, OrderStatus next) {
190	        if (!stored.order().status().canTransitionTo(next)) {
191	            throw ApiException.conflict("OPERATION_NOT_ALLOWED");
192	        }
193	    }
194	
195	    private static ApiException notFound() {
196	        return ApiException.notFound("ORDER_NOT_FOUND");
197	    }
198	
199	    private static Instant parseInstant(String text) {
200	        if (text == null) {
201	            return null;
202	        }
203	        try {
204	            return OffsetDateTime.parse(text).toInstant();
205	        } catch (RuntimeException e) {
206	            return null;
207	        }
208	    }
209	
210	    private <T> T inTransaction(Supplier<T> work) {
211	        return tx.execute(status -> work.get());
212	    }
213	
214	    private record PaymentResult(Order order, ApiException error) {
215	    }
216	}
